const subject = label(t.subject);
const ticket_text = (t.conversation || []).map(m => `${m.from}: ${label(m.text)}`).concat(t.resolution ? [`Resolution: ${label(t.resolution)}`] : []).join('\n');
const remaining = personalData(subject + '\n' + ticket_text, t, cfg);
return [{ json: { clean: remaining.length === 0, remaining, subject, ticket_text } }];
})())[0];
DATA["Steps 3 and 4: Rule: replace customer details, then check none remain"] = [{ json: r }];
if (r.clean) return [{ json: Object.assign({ route: 'clean' }, r) }];
return [{ json: Object.assign({}, r, one((() => { return [{ json: { route: 'set_aside', reason: 'personal data remains', detail: $('Steps 3 and 4: Rule: replace customer details, then check none remain').first().json.remaining.join(', ') } }]; })())[0]) }];
};
const out = one(__rule())[0] || {};
return Object.assign({}, out, BODIES(out));

